#include <algorithm>
#include <unordered_map>
#include <vector>
using namespace std;

class Solution {
public:
    int numFactoredBinaryTrees(vector<int>& arr) {
        constexpr long long MOD = 1000000007;
        sort(arr.begin(), arr.end());

        unordered_map<int, long long> ways;
        ways.reserve(arr.size() * 2);

        long long answer = 0;

        for (int i = 0; i < static_cast<int>(arr.size()); ++i) {
            long long count = 1;

            for (int j = 0; j < i; ++j) {
                if (arr[i] % arr[j] != 0) {
                    continue;
                }

                int right = arr[i] / arr[j];
                auto it = ways.find(right);
                if (it != ways.end()) {
                    count = (count + ways.at(arr[j]) * it->second) % MOD;
                }
            }

            ways.emplace(arr[i], count);
            answer = (answer + count) % MOD;
        }

        return static_cast<int>(answer);
    }
};

